62: func greenhouseElapsedSummary(watch store.GreenhouseTaskWatch, now time.Time) string {
63: 	runStart := watch.RunStartedAt
64: 	if runStart == 0 {
65: 		runStart = watch.RunObservedAt
66: 	}
