296: func (s *Service) reportGreenhouseTaskMetadata(ctx context.Context, db *store.DB, project store.Project, task store.Task, watch store.GreenhouseTaskWatch, snapshot greenhouseWatchSnapshot) {
297: 	if task.HerdrWorkspaceID == "" || s.Herdr == nil {
298: 		return
299: 	}
300: 	now := time.Now()
301: 	label := greenhouseElapsedSummary(watch, now)
302: 	if snapshot.Run.Pipeline != nil && snapshot.Run.Pipeline.RepairLimit > 0 {
303: 		label = watch.Stage + " · fix " + fmt.Sprintf("%d/%d", snapshot.Run.Pipeline.RepairUsed, snapshot.Run.Pipeline.RepairLimit)
304: 	}
305: 	if watch.Status == "needs-decision" {
306: 		label = "waiting for decision"
307: 	} else if watch.Status == "ci-ready" || watch.Status == "locally-ready" {
308: 		label = "PR green"
309: 	} else if watch.Status == "failed" || watch.Status == "recovery-required" {
310: 		label = "failed: " + strings.TrimSpace(watch.Stage)
311: 	}
312: 	notices, err := db.UndeliveredNotices(ctx, project.ID)
313: 	if err != nil {
314: 		return
315: 	}
316: 	_, _ = s.herdrCall(ctx, "workspace.report_metadata", map[string]any{
317: 		"workspace_id": task.HerdrWorkspaceID, "source": "posse",
318: 		"tokens": map[string]string{"posse": fmt.Sprint(len(notices)), "greenhouse": label},
319: 	})
320: }
