const taskSignals = `-- name: TaskSignals :many
SELECT id, task_id, verb, note, data_json, at FROM signals
WHERE task_id = ? ORDER BY id DESC LIMIT ?
`

type TaskSignalsParams struct {
	TaskID int64
	Limit  int64
}

func (q *Queries) TaskSignals(ctx context.Context, arg TaskSignalsParams) ([]Signal, error) {
	rows, err := q.db.QueryContext(ctx, taskSignals, arg.TaskID, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Signal{}
	for rows.Next() {
		var i Signal
		if err := rows.Scan(
			&i.ID,
			&i.TaskID,
			&i.Verb,
			&i.Note,
			&i.DataJson,
			&i.At,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

