+			watch.StageObservedAt = now
+		}
+		if runStarted > 0 {
+			watch.RunStartedAt = runStarted
+		}
+		if stageStarted > 0 {
+			watch.StageStartedAt = stageStarted
+		} else if stage != watch.Stage {
+			watch.StageStartedAt = 0
+		}
+		if stageFinished > 0 {
+			watch.StageFinishedAt = stageFinished
+		} else if stage != watch.Stage {
+			watch.StageFinishedAt = 0
