322: func greenhousePaneExists(ctx context.Context, s *Service, task store.Task, paneID string) bool {
323: 	if paneID == "" || s.Herdr == nil {
324: 		return false
325: 	}
326: 	snapshot, err := s.snapshot(ctx)
327: 	if err != nil {
328: 		return false
329: 	}
330: 	for _, pane := range snapshot.Panes {
331: 		if pane.PaneID == paneID && pane.WorkspaceID == task.HerdrWorkspaceID {
332: 			return true
333: 		}
334: 	}
335: 	return false
336: }
