+	if _, err := db.AddSignal(ctx, taskID, "done", "pipeline complete", map[string]string{"greenhouse_run_id": "run-1046"}); err != nil {
+		t.Fatal(err)
+	}
+	task, err := db.TaskByID(ctx, project.ID, taskID)
+	if err != nil {
+		t.Fatal(err)
+	}
