+	watchEnv := setEnv(greenhouseEnv, "POSSE_WATCH_TOKEN", "")
+	if output, err := runBinaryAllowFailure(f.binary, f.repo, watchEnv, "watch", "--poll-only", "--timeout", "1000"); err != nil {
